let trig = {};
try { trig = $('When Called (Import Plan)').first().json || {}; } catch (err) { trig = {}; }
const src = Array.isArray(trig.ics_events) ? trig.ics_events : $input.all().map(i => i.json);
const events = src.filter(e => e && e.status !== 'cancelled' && e.start);
const sportOf = (s) => {
  if (s.startsWith('🚴')) return 'Ride';
  if (s.startsWith('🏃')) return 'Run';
  if (s.startsWith('🏋') || s.startsWith('💪') || s.startsWith('🧘')) return 'Strength';
  if (s.startsWith('🏁')) return /MTB|XC|ride|bike|trainer/i.test(s) ? 'Ride' : 'Run';
  if (/rest/i.test(s)) return 'Rest';
  return 'Other';
};
const workouts = events.map(e => {
  const s = e.summary || 'Workout';
  const d = e.description || '';
  const startIso = e.start.dateTime || e.start.date;
  const endIso = (e.end && (e.end.dateTime || e.end.date)) || startIso;
  const dur = d.match(/Planned Duration:\s*([\d.]+)\s*min/i);
  let mins = dur ? Math.round(parseFloat(dur[1])) : Math.round((new Date(endIso) - new Date(startIso)) / 60000);
  if (!mins || mins < 0 || mins > 600) mins = 60;
  const title = s.replace(/^[^\p{L}\p{N}]+/u, '').trim().substring(0, 150);
  return {
    scheduled_date: String(startIso).substring(0, 10),
    sport_type: sportOf(s),
    title: title || 'Workout',
    description: (s + (d ? '\n\n' + d : '')).substring(0, 4000),
    target_duration_mins: mins
  };
});
return [{ json: {
  telegram_id: trig.telegram_id ? String(trig.telegram_id) : '',
  chat_id: trig.chat_id ? String(trig.chat_id) : '',
  count: workouts.length,
  first_date: workouts.length ? workouts[0].scheduled_date : null,
  last_date: workouts.length ? workouts[workouts.length - 1].scheduled_date : null,
  workouts_json: JSON.stringify(workouts)
} }];
